using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using MC2Pack;
namespace Astera {
public sealed class PrismInstance {
 public string Root,GameRoot,Name,Id,Minecraft,Loader,LoaderKind;
 public override string ToString(){return Name+" — "+Id;}
}
static class PrismProfiles {
 internal static string DefaultData {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"PrismLauncher");}}
 internal static string DefaultExecutable(){return new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","PrismLauncher","prismlauncher.exe"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"PrismLauncher","prismlauncher.exe")}.FirstOrDefault(File.Exists)??"";}
 internal static void SafePath(string value){string at=Path.GetFullPath(value);while(at!=null){Engine.Plain(at);at=Path.GetDirectoryName(at);}}
 internal static Dictionary<string,string> Ini(string path){var values=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);if(!File.Exists(path))return values;SafePath(path);if(new FileInfo(path).Length>1024*1024)throw new IOException("Launcher settings are too large");bool general=false;foreach(string raw in File.ReadAllLines(path)){string line=raw.Trim();if(line.StartsWith("[")){general=line.Equals("[General]",StringComparison.OrdinalIgnoreCase);continue;}int equals=line.IndexOf('=');if(!general||equals<1||line.StartsWith(";")||line.StartsWith("#"))continue;string value=line.Substring(equals+1).Trim();if(value.StartsWith("\"")&&value.EndsWith("\"")&&value.Length>1)value=value.Substring(1,value.Length-2);values[line.Substring(0,equals).Trim()]=value.Replace("\\\\","\\");}return values;}
 internal static string InstanceDirectory(string data){data=Engine.Root(data);SafePath(data);string value;var ini=Ini(Path.Combine(data,"prismlauncher.cfg"));if(!ini.TryGetValue("InstanceDir",out value)||String.IsNullOrWhiteSpace(value))value="instances";if(value.Any(Char.IsControl)||value.StartsWith("@"))throw new IOException("Choose the Prism instances folder manually; this launcher path format is unsupported");string root=Path.GetFullPath(Path.IsPathRooted(value)?value:Path.Combine(data,value));SafePath(root);return root;}
 internal static string ResolveRoot(string path){string root=Engine.Root(path);SafePath(root);if(File.Exists(Path.Combine(root,"mmc-pack.json")))return root;string name=Path.GetFileName(root);if(name=="minecraft"||name==".minecraft"){string parent=Path.GetDirectoryName(root);if(File.Exists(Path.Combine(parent,"mmc-pack.json")))return parent;}throw new IOException("Choose a Prism instance folder, or its minecraft folder");}
 internal static bool HasGameMetadata(string game){string name=Path.GetFileName(game.TrimEnd('\\','/'));return (name=="minecraft"||name==".minecraft")&&File.Exists(Path.Combine(Path.GetDirectoryName(game),"mmc-pack.json"));}
 internal static PrismInstance Read(string path){string root=ResolveRoot(path);string cfg=Path.Combine(root,"instance.cfg"),pack=Path.Combine(root,"mmc-pack.json");if(!File.Exists(cfg)||new FileInfo(pack).Length>1024*1024)throw new IOException("Prism instance metadata is missing or too large");SafePath(cfg);var settings=Ini(cfg);string type;if(!settings.TryGetValue("InstanceType",out type)||type!="OneSix")throw new IOException("Choose a modern Prism Minecraft instance");var data=Engine.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(pack));object raw;if(data==null||!data.TryGetValue("formatVersion",out raw)||Convert.ToInt32(raw)!=1||!data.TryGetValue("components",out raw)||!(raw is IEnumerable))throw new IOException("Unsupported Prism instance metadata");string mc=null,fabric=null,other=null;var ids=new HashSet<string>();foreach(object item in (IEnumerable)raw){var component=item as Dictionary<string,object>;object uidValue,versionValue;if(component==null||!component.TryGetValue("uid",out uidValue)||!(uidValue is string))throw new IOException("Invalid Prism component");string uid=(string)uidValue;if(!ids.Add(uid))throw new IOException("Duplicate Prism component");object disabled;if(component.TryGetValue("disabled",out disabled)&&Convert.ToBoolean(disabled))continue;string version=component.TryGetValue("version",out versionValue)?Convert.ToString(versionValue):"";if(uid=="net.minecraft")mc=version;else if(uid=="net.fabricmc.fabric-loader")fabric=version;else if(uid.IndexOf("forge",StringComparison.OrdinalIgnoreCase)>=0||uid.IndexOf("quilt",StringComparison.OrdinalIgnoreCase)>=0)other=uid;}
  if(String.IsNullOrEmpty(mc))throw new IOException("Prism instance has no enabled Minecraft version");string modern=Path.Combine(root,"minecraft"),legacy=Path.Combine(root,".minecraft");string game=Directory.Exists(legacy)&&!Directory.Exists(modern)?legacy:modern;SafePath(game);string name;return new PrismInstance{Root=root,GameRoot=game,Id=Path.GetFileName(root),Name=settings.TryGetValue("name",out name)?name:Path.GetFileName(root),Minecraft=mc,Loader=fabric,LoaderKind=other??(fabric==null?"vanilla":"fabric")};}
 internal static void ValidateRuntime(string game,Release release){var profile=Read(game);if(!profile.GameRoot.Equals(Engine.Root(game),StringComparison.OrdinalIgnoreCase))throw new IOException("Choose this Prism instance's active Minecraft folder");Version have,want;if(profile.LoaderKind!="fabric"||profile.Minecraft!=release.Minecraft||!Version.TryParse(profile.Loader,out have)||!Version.TryParse(release.Loader,out want)||have<want)throw new IOException("In Prism, select Minecraft "+release.Minecraft+" and Fabric "+release.Loader+" or newer first");foreach(string uid in new[]{"net.minecraft","net.fabricmc.fabric-loader"})if(File.Exists(Path.Combine(profile.Root,"patches",uid+".json")))throw new IOException("Custom Prism runtime patches cannot be verified. Use a standard Fabric instance for Minecraft²");}
 internal static List<PrismInstance> Discover(string data){string instances=InstanceDirectory(data);var found=new List<PrismInstance>();if(!Directory.Exists(instances))return found;foreach(string root in Directory.GetDirectories(instances).Take(1000))try{found.Add(Read(root));}catch(IOException){}catch(UnauthorizedAccessException){}catch(ArgumentException){}return found.OrderBy(x=>x.Name,StringComparer.OrdinalIgnoreCase).ToList();}
 internal static PrismInstance Create(string data,Release release,bool vanilla=false){Engine.Validate(release);if(!Regex.IsMatch(release.Minecraft??"","\\A[0-9A-Za-z.+_-]{1,80}\\z")||!Regex.IsMatch(release.Loader??"","\\A[0-9]+\\.[0-9]+\\.[0-9]+\\z"))throw new IOException("Unsupported Minecraft runtime version");string instances=InstanceDirectory(data);Directory.CreateDirectory(instances);SafePath(instances);string root=Path.Combine(instances,vanilla?"Vanilla":"Minecraft-Squared");for(int i=2;Directory.Exists(root)||File.Exists(root);i++)root=Path.Combine(instances,(vanilla?"Vanilla-":"Minecraft-Squared-")+i);string stage=Path.Combine(instances,".astera-prism-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);try{Directory.CreateDirectory(Path.Combine(stage,"minecraft"));File.WriteAllText(Path.Combine(stage,"mmc-pack.json"),Engine.Json.Serialize(new{formatVersion=1,components=vanilla?new[]{new{uid="net.minecraft",version=release.Minecraft,important=true}}:new[]{new{uid="net.minecraft",version=release.Minecraft,important=true},new{uid="net.fabricmc.fabric-loader",version=release.Loader,important=true}}}),new UTF8Encoding(false));File.WriteAllText(Path.Combine(stage,"instance.cfg"),"[General]\nInstanceType=OneSix\nname="+(vanilla?"Vanilla":"Minecraft²")+"\niconKey=default\nOverrideMemory=true\nMinMemAlloc=1024\nMaxMemAlloc="+(vanilla?"4096":"6144")+"\n",new UTF8Encoding(false));Directory.Move(stage,root);return Read(root);}finally{if(Directory.Exists(stage)){SafePath(stage);foreach(string file in new[]{"mmc-pack.json","instance.cfg"})if(File.Exists(Path.Combine(stage,file)))File.Delete(Path.Combine(stage,file));string game=Path.Combine(stage,"minecraft");if(Directory.Exists(game)&&!Directory.EnumerateFileSystemEntries(game).Any())Directory.Delete(game);if(!Directory.EnumerateFileSystemEntries(stage).Any())Directory.Delete(stage);}}}
 internal static ProcessStartInfo Launch(string executable,string data,string game){var profile=Read(game);string instances=InstanceDirectory(data);if(!Path.GetDirectoryName(profile.Root).Equals(instances,StringComparison.OrdinalIgnoreCase))throw new IOException("This instance belongs to a different Prism library. Choose its launcher data folder in Settings");if(!File.Exists(executable)||!Path.GetFileName(executable).Equals("prismlauncher.exe",StringComparison.OrdinalIgnoreCase))throw new IOException("Choose Prism Launcher's prismlauncher.exe in Minecraft² settings");SafePath(executable);return new ProcessStartInfo(executable){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(executable),Arguments="--dir "+Quote(Engine.Root(data))+" --launch "+Quote(profile.Id)};}
 internal static string Quote(string value){if(value.IndexOf('"')>=0||value.Any(Char.IsControl))throw new IOException("Invalid launcher argument");return "\""+value.TrimEnd('\\')+"\"";}
}
}
